package com.shopsphere;
import com.fasterxml.jackson.core.JsonProcessingException;import com.fasterxml.jackson.databind.ObjectMapper;import java.time.Duration;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.data.redis.core.StringRedisTemplate;import org.springframework.stereotype.Repository;
@Repository class RedisCartRepository implements CartRepository{private static final String PREFIX="shopsphere:cart:";private final StringRedisTemplate redis;private final ObjectMapper json;private final Duration ttl;RedisCartRepository(StringRedisTemplate r,ObjectMapper j,@Value("${shopsphere.cart.ttl-hours:72}")long hours){redis=r;json=j;ttl=Duration.ofHours(hours);}public Optional<Cart>find(UUID user){String value=redis.opsForValue().get(key(user));if(value==null)return Optional.empty();try{return Optional.of(json.readValue(value,Cart.class));}catch(JsonProcessingException e){throw new IllegalStateException("Invalid cart payload in Redis",e);}}public Cart save(Cart cart){try{redis.opsForValue().set(key(cart.userId()),json.writeValueAsString(cart),ttl);return cart;}catch(JsonProcessingException e){throw new IllegalStateException("Unable to serialize cart",e);}}public void delete(UUID user){redis.delete(key(user));}private String key(UUID user){return PREFIX+user;}}
